import numpy as np
def equation(eps, T, params):
    p = params
    L = np.log(1+eps)
    z = p[0] + p[1]*T**p[2] + (p[3] + p[4]*T**p[5])*L + (p[6] + p[7]*T)*L**2 + p[8]*L**3 + p[9]*T*L**3
    return np.exp(z)
